    "configureSetsUpAtqg62": "Configure sets up a run. Current Run shows live loss and metrics once it starts. History keeps every past run, so you can reopen, resume or export one. Image and diffusion training lives on the Images page.",
    "eachStemGetsItsl6ver": "Each stem gets its own row with solo, mute and volume, all playing in sync. Download one stem or all of them.",
    "itFillsInBy1u22x": "It fills in by itself. Fix any word the recognizer got wrong so it matches what's said.",
    "lAiMServesAnOpenAIl3zmk": "LAiM serves an OpenAI-compatible API. Point any client at this base URL, keep the model name the same, and it works. Status and queue slots sit beside it.",
    "loadingOneReplacesTheosq6j": "Loading one replaces the model in the main slot.",
    "lyricsPlusADescriptionvbic3": "Lyrics, plus a description of the style where the model takes one. Length sits under Advanced.",
    "modelsThatCanChange1hq71": "Models that can change words in a recording and keep the voice.",
    "modelsThatCanSpeak15zt7": "Models that can speak in the voice of a short recording you give them.",
    "musicModels1im3u": "Music models.",
    "openThePageTitle1edk4": "Open the page title to switch pages. Speak turns text into speech, Clone speaks in the voice from a short recording, Edit changes words in a recording, Convert makes a recording sound like another voice, Music makes songs and sound effects, Separate splits a track into vocals and instruments, and Transcribe turns a recording into text. Each lists only the models that can do it, so the picker above follows the page.",
    "promptResolutionDurationIn1rxvi": "Prompt, resolution, duration in frames, steps, guidance and seed. Duration and resolution drive VRAM and time most, so start small.",
    "qLoRATrainsAdaptersOn49tuo": "QLoRA trains adapters on a 4-bit base and needs the least VRAM. LoRA does the same in 16-bit. Full fine-tune updates every weight. Continued pretraining is for teaching a new domain or language.",
    "recipesAreStoredOn1p6oi": "Recipes are stored on this device. Save before a long run.",
    "recordFromYourMicrophonecujmp": "Record from your microphone and it transcribes when you stop, or upload a wav, mp3, m4a or webm file instead.",
    "resultsPlayHereAnd1ydl5": "Results play here and stay in the history list. Switch between Source and Converted to hear the difference at the same moment.",
    "searchByNameOr5l10l": "Search by name, or paste",
    "searchHuggingFaceReuse12nau": "Search Hugging Face, reuse a model already on this device, or paste",
    "searchTheHubOr1hf31": "Search the Hub, or upload PDF, DOCX, JSONL, JSON, CSV or Parquet. Preview a few rows before you start, since formatting matters more than size. We map the columns for you and ask only when the format is unclear. No dataset yet? Build one on the Recipes page.",
    "sensibleHyperparametersSmallerModeerr7z": "sensible hyperparameters. Smaller models iterate faster, so scale up once the data looks right. GGUF files cannot be trained.",
    "simpleCoversEpochsLearning5tnd7": "Simple covers epochs, learning rate, batch size and context length. Advanced opens LoRA rank, schedulers, eval and checkpointing. Defaults come from the model you picked, so change one knob at a time. 1 to 3 epochs is a good start.",
    "someModelsNeedThe2qk5z": "Some models need the clip's words to match its voice. Type them or press Transcribe.",
    "sourceSeparationModels7i1a0": "Source separation models.",
    "speechRecognitionModelsThey1p9vq": "Speech recognition models. They run beside your chat model, not in its place.",
    "textToSpeechModelse4pii": "Text-to-speech models, including voices you fine-tuned under On Device.",
    "theSelectedClipPlays12tt9": "The selected clip plays here and every clip lines up below. Download it, or reuse its settings for the next run.",
    "theVoiceItShould1qgmy": "The voice it should sound like: a short clip, a saved voice, or one of the model's built-in voices.",
    "toJumpStraightToum4jg": "to jump straight to a repo. LAiM's own quants rank first.",
    "uploadRecordOrPick10wjy": "Upload, record or pick up to 30 seconds of one voice from your history.",
    "uploadRecordOrPick164by": "Upload, record or pick the speech or singing to convert. Its words and timing stay; only the voice changes.",
